card_capture_audit.query:
BEGIN READ ONLY;
WITH t AS (SELECT race_key,cname,(race_date::text||' '||replace(replace(post_time,'時',':'),'分','')||':00+09')::timestamptz post_at FROM public.jra_live_races WHERE race_date='2026-11-23' AND track='東京' AND race_no=12)
SELECT e.id,e.race_key,e.cname,e.source_url,e.fetched_at,e.recorded_at,e.html_sha256,e.html_bytes,e.extractor_version,e.status_basis,e.official_status_verified,e.runner_count,e.fetched_at<t.post_at AND e.recorded_at<t.post_at AS both_prestart FROM t JOIN public.jra_html_evidence e ON e.race_key=t.race_key OR e.cname=t.cname ORDER BY e.fetched_at;
ROLLBACK;
